// Gap 3.3: refuse to replay a request body across an HTTPS → HTTP
// downgrade. A malicious 307 from an HTTPS endpoint to its HTTP twin
// would otherwise leak the form-encoded body in plaintext on the wire.
func TestDefaultApiClient_RefusesBodyReplayOnHttpsToHttpDowngrade(t *testing.T) {
	t.Parallel()
	plainServer := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(200)
	}))
	defer plainServer.Close()

	tlsServer := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Location", plainServer.URL+"/leaked")
		w.WriteHeader(307)
	}))
	defer tlsServer.Close()

	transport, buildErr := NewTransportOptionsBuilder().
		VerifySsl(false).
		FollowRedirects(true).
		Build()
	if buildErr != nil {
		t.Fatal(buildErr)
	}
	client := NewDefaultApiClient(transport)
	_, err := client.SendRequest(
		"POST", tlsServer.URL+"/issue",
		map[string]string{"Content-Type": "application/x-www-form-urlencoded"},
		[]byte("client_secret=hunter2"),
	)
	if err == nil {
		t.Fatal("expected error refusing HTTPS→HTTP body replay, got nil")
	}
	if !strings.Contains(err.Error(), "HTTPS") || !strings.Contains(err.Error(), "HTTP") {
		t.Errorf("expected downgrade refusal message, got %q", err.Error())
	}
}

// Gap 3.4: when a 303 forces the follow-up to GET and clears the body,
// the outbound request must also drop the Content-Length header so it
// reflects the now-empty body. Stale Content-Length on a GET trips some
// origins / proxies and is undefined per RFC 7231 §3.3.2.
func TestDefaultApiClient_Drops303ContentLengthOnCoercedGet(t *testing.T) {
	t.Parallel()
	var sawContentLengthOnGet string
	var sawMethodOnFollowup string
	mux := http.NewServeMux()
	mux.HandleFunc("/post", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Location", "/followup")
		w.WriteHeader(303)
	})
	mux.HandleFunc("/followup", func(w http.ResponseWriter, r *http.Request) {
		sawMethodOnFollowup = r.Method
		sawContentLengthOnGet = r.Header.Get("Content-Length")
		w.WriteHeader(200)
	})
	server := httptest.NewServer(mux)
	defer server.Close()

	transport, buildErr := NewTransportOptionsBuilder().
		FollowRedirects(true).
		Build()
	if buildErr != nil {
		t.Fatal(buildErr)
	}
	client := NewDefaultApiClient(transport)
	_, err := client.SendRequest(
		"POST", server.URL+"/post",
		map[string]string{"Content-Type": "application/json"},
		[]byte(`{"hello":"world"}`),
	)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if sawMethodOnFollowup != "GET" {
		t.Errorf("expected GET on 303 follow-up, got %q", sawMethodOnFollowup)
	}
	if sawContentLengthOnGet != "" && sawContentLengthOnGet != "0" {
		t.Errorf("expected Content-Length to be dropped (or 0) on 303 follow-up, got %q",
			sawContentLengthOnGet)
	}
}

// A 301 / 302 / 303 demotes a POST to a bodyless GET. net/http re-copies the
// original request's headers onto each hop, so the follow-up must have the
// entity headers stripped, or it would send a Content-Type with no body.
func TestDefaultApiClient_DemotedGetDropsEntityHeaders(t *testing.T) {
	t.Parallel()
	for _, status := range []int{301, 302, 303} {
		status := status
		t.Run(fmt.Sprintf("status_%d", status), func(t *testing.T) {
			t.Parallel()
			var sawMethod, sawContentType, sawContentLength string
			mux := http.NewServeMux()
			mux.HandleFunc("/post", func(w http.ResponseWriter, r *http.Request) {
				w.Header().Set("Location", "/followup")
				w.WriteHeader(status)
			})
			mux.HandleFunc("/followup", func(w http.ResponseWriter, r *http.Request) {
				sawMethod = r.Method
				sawContentType = r.Header.Get("Content-Type")
				sawContentLength = r.Header.Get("Content-Length")
				w.WriteHeader(200)
			})
			server := httptest.NewServer(mux)
			defer server.Close()

			transport, buildErr := NewTransportOptionsBuilder().FollowRedirects(true).Build()
			if buildErr != nil {
				t.Fatal(buildErr)
			}
			client := NewDefaultApiClient(transport)
			_, err := client.SendRequest(
				"POST", server.URL+"/post",
				map[string]string{"Content-Type": "application/json"},
				[]byte(`{"hello":"world"}`),
			)
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if sawMethod != "GET" {
				t.Errorf("expected GET on the %d follow-up, got %q", status, sawMethod)
			}
			if sawContentType != "" {
				t.Errorf("expected no Content-Type on the %d follow-up, got %q", status, sawContentType)
			}
			if sawContentLength != "" {
				t.Errorf("expected no Content-Length on the %d follow-up, got %q", status, sawContentLength)
			}
		})
	}
}

// Gap 3.1: an API-key header name harvested from the OpenAPI spec must be
// stripped from a cross-origin 3xx redirect alongside the static sensitive
// allowlist (Authorization, Cookie, Proxy-Authorization). When the spec
// declares no API-key headers the dynamic portion of the allowlist is
// empty and only the static names are present; the static names are
// always stripped regardless of spec content.
func TestDefaultApiClient_StripsAuthorizationAcrossCrossOriginRedirect(t *testing.T) {
	t.Parallel()
	var receivedAuth string
	target := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		receivedAuth = r.Header.Get("Authorization")
		w.WriteHeader(200)
	}))
	defer target.Close()

	origin := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Location", target.URL+"/followed")
		w.WriteHeader(302)
	}))
	defer origin.Close()

	transport, buildErr := NewTransportOptionsBuilder().
		FollowRedirects(true).
		Build()
	if buildErr != nil {
		t.Fatal(buildErr)
	}
	client := NewDefaultApiClient(transport)
	_, err := client.SendRequest("GET", origin.URL+"/start",
		map[string]string{"Authorization": "Bearer leaked-token"}, nil)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if receivedAuth != "" {
		t.Errorf("expected Authorization to be stripped across cross-origin redirect, got %q",
			receivedAuth)
	}
}

// Gap 3.1: the spec-declared API-key header names harvested from the OpenAPI
// securitySchemes (apiKey, in: header) must be present in the cross-origin
// sensitive-header allowlist alongside the static trio.
func TestDefaultApiClient_SpecDeclaredApiKeyHeaderNamesAreSensitive(t *testing.T) {
	t.Parallel()
	contains := func(name string) bool {
		for _, h := range sensitiveHeaderAllowlist {
			if strings.EqualFold(h, name) {
				return true
			}
		}
		return false
	}
	if !contains("X-API-Key") {
		t.Errorf("expected spec-declared API-key header %q to be in sensitiveHeaderAllowlist, got %v",
			"X-API-Key", sensitiveHeaderAllowlist)
	}
	if !contains("X-Internal-Key") {
		t.Errorf("expected spec-declared API-key header %q to be in sensitiveHeaderAllowlist, got %v",
			"X-Internal-Key", sensitiveHeaderAllowlist)
	}
}

// Gap 3.1: a caller-provided, spec-declared API-key header must be stripped
// from a cross-origin 3xx redirect, exactly like the static credential trio,
// so the key is never leaked to a different origin.
func TestDefaultApiClient_StripsApiKeyHeaderAcrossCrossOriginRedirect(t *testing.T) {
	t.Parallel()
	// Use the first spec-declared API-key header for the assertion.
	apiKeyHeader := []string{
		"X-API-Key", "X-Internal-Key",
	}[0]

	var receivedKey string
	target := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		receivedKey = r.Header.Get(apiKeyHeader)
		w.WriteHeader(200)
	}))
	defer target.Close()

	origin := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Location", target.URL+"/followed")
		w.WriteHeader(302)
	}))
	defer origin.Close()

	transport, buildErr := NewTransportOptionsBuilder().
		FollowRedirects(true).
		Build()
	if buildErr != nil {
		t.Fatal(buildErr)
	}
	client := NewDefaultApiClient(transport)
	_, err := client.SendRequest("GET", origin.URL+"/start",
		map[string]string{apiKeyHeader: "secret-api-key-value"}, nil)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if receivedKey != "" {
		t.Errorf("expected API-key header %q to be stripped across cross-origin redirect, got %q",
			apiKeyHeader, receivedKey)
	}
}

// close-lifecycle-three-way: sending a request after Close() is a caller
// mistake. It fails with the ErrClientClosed sentinel, not an SDK error, and
// never silently succeeds or leaks a foreign library error.
func TestDefaultApiClient_UseAfterCloseReturnsErrClientClosed(t *testing.T) {
	t.Parallel()
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(200)
	}))
	defer server.Close()

	client := NewDefaultApiClient(nil)
	if err := client.Close(); err != nil {
		t.Fatalf("Close returned error: %v", err)
	}

	_, err := client.SendRequest("GET", server.URL+"/test", map[string]string{}, nil)
	if !errors.Is(err, ErrClientClosed) {
		t.Fatalf("expected ErrClientClosed, got %T: %v", err, err)
	}
	var root pkgerrors.OpenAPIError
	if errors.As(err, &root) {
		t.Errorf("use after close must not be a OpenAPIError, got %T", err)
	}
}

